import{_ as a,H as t,f as p,i as c}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"结束语 | 对React和前端技术未来的展望","description":"","frontmatter":{},"headers":[{"level":2,"title":"前端技术的变与不变","slug":"前端技术的变与不变","link":"#前端技术的变与不变","children":[]},{"level":2,"title":"对 React 和前端未来的展望","slug":"对-react-和前端未来的展望","link":"#对-react-和前端未来的展望","children":[]},{"level":2,"title":"写在最后","slug":"写在最后","link":"#写在最后","children":[]}],"relativePath":"现代ReactWeb开发实战/结束语｜对React和前端技术未来的展望.md","filePath":"现代ReactWeb开发实战/结束语｜对React和前端技术未来的展望.md","lastUpdated":1795558962000}'),i={name:"现代ReactWeb开发实战/结束语｜对React和前端技术未来的展望.md"};function l(r,e,s,n,o,R){return t(),p("div",null,[...e[0]||(e[0]=[c('<h1 id="结束语-对react和前端技术未来的展望" tabindex="-1">结束语 | 对React和前端技术未来的展望 <a class="header-anchor" href="#结束语-对react和前端技术未来的展望" aria-label="Permalink to &quot;结束语 | 对React和前端技术未来的展望&quot;">​</a></h1><p>你好，我是宋一玮。</p><p>时间过得真快，从 5 月底《现代 React Web 开发实战》专栏开始立项，8 月下旬开始连载，转眼就到 10 月下旬连载结束了。</p><p>这里我想先重提一下我在开篇词中对你的期望：学习一门技术，务必要有大于一门技术的收获。</p><p>之所以有这个初衷，是因为我从业 16 年，深刻理解到，软件开发的从业者需要具有终身学习的能力和决心。然而随着离开学校步入职场，之后再经历过职业或人生的一些重要阶段，我们可以用于学习的时间和精力只会越来越少、越来越碎片化。</p><p>不论是追逐理想还是直面功利，学习新技术时都值得多花些心思：如何用有限的学习换来更多的收获。</p><p>这个专栏整体都是按照这个初衷设计的。如果回头翻翻目录你会发现：</p><ul><li><p>历史篇在复习（了解）前端开发技术历史的同时，尝试用你可能已经熟悉的知识引出React；</p></li><li><p>“独狼”篇一开始，通过一个简单的看板项目为你演示如何开发 React 应用，然后抽丝剥茧，一边讲解 React 中的概念和 API，一边介绍背后的前端领域知识；</p></li><li><p>项目篇则是选出大中型 React 项目中会遇到的典型挑战，跳出 React 技术分析这些挑战的本质，然后再回到 React 中解决它们。</p></li></ul><p>不知你经过这个专栏的学习，是否有比 React 技术本身更多的收获呢？</p><h2 id="前端技术的变与不变" tabindex="-1">前端技术的变与不变 <a class="header-anchor" href="#前端技术的变与不变" aria-label="Permalink to &quot;前端技术的变与不变&quot;">​</a></h2><p>专栏的第 1 节课，曾用 Java Web 技术与包括 React 在内的现代 JS Web 技术做对比，讨论了前端技术的变与不变。这里我不打算再反复强调哪些技术点会变，哪些不会变。而是换个角度，聊聊前端开发者。</p><p>如今网络上的信息极为丰富，甚至是过载的。只要简单搜索，你就可以得到很多既成的结论，比如新技术 A 就是老技术 M 的马甲，新技术 B 就是老技术 X、Y、Z 的缝合，新技术 C 刚推出就过时了等等。</p><p>这些可以信，但不建议尽信。快速了解技术的变与不变，多少可以走些捷径，但如果一个开发者所有的判断都来自二手或三手资料，那这些判断只会越来越虚。</p><p>陆游说得好：</p><ul><li>纸上得来终觉浅，绝知此事要躬行。</li></ul><p>一位经验丰富的前端开发者并不等于优秀的前端开发者，但任何组织任何人都不应该否定经验的价值。经验不仅代表过去，更可以支撑起一个可预期的未来（这样说主要还是为 35 岁以上的开发者正名）。年轻的同学们也不妨戒骄戒躁，攒经验本来也是一个量变到质变的过程，你今天学过的、做过的，都会成为以后的财富。</p><h2 id="对-react-和前端未来的展望" tabindex="-1">对 React 和前端未来的展望 <a class="header-anchor" href="#对-react-和前端未来的展望" aria-label="Permalink to &quot;对 React 和前端未来的展望&quot;">​</a></h2><p>在这次专栏写作过程中，为了获得 React 18 新版本的一手资料，我阅读了大量 React 源码。老实说，这次阅读源码是比较辛苦的，一是写作节奏比较紧张，二是要纠正许多在 React 老版本中的概念和逻辑的理解，这里也要感谢专栏留言区部分同学们的输入。</p><p>当时也看到了 React 核心团队成员，对 React 的 Fiber 协调引擎和调度器的一些解释。当有网友问，这套异步机制是不是在为浏览器 JS 实现多线程？团队的回答很巧妙：“是，也不是。”</p><p>之所以回答“是”，是因为 Fiber 确实在使用一套自己的方式来分解和调度任务（工作），来避免浏览器线程被阻塞。之所以回答“不是”，是因为这套方式比多线程更加轻量，不涉及线程通信、线程同步 / 线程锁。</p><p>其实我也在想，保证工作不阻塞这件事本身，是不是应该交由浏览器来做？现代浏览器确实包含了类似技术，如 Web Worker、WebAssembly 甚至 iFrame。但每个技术都有它原本的使用场景，如果拿来当成多线程来用，都会存在不少的 Hack。</p><p>未来浏览器会不会为 JS 加入原生多线程？也许会，也许不会。单就目前的 React 技术而言，它已找到了适合它自己的技术路线，即 Fiber。所以我理解 React 并不迫切需要浏览器原生支持多线程。</p><p>React 以外的其他 Web 前端框架会引入 Fiber 吗？我认为机会不大，Fiber 之所以适合React，不只是因为 React 面对的应用场景，更是因为 React 的历史包袱（说人家类组件是历史包袱有点过分吧？）。假设 React 推翻重来，从函数组件 +Hooks 开始重新设计开发，相信Fiber 中的抽象层次一定会有所简化，调度逻辑也可能有相应的变化。</p><p>回到 React API 层面。一个框架的发展有点像企业扩张，企业的主要扩张方式包括横向一体化和纵向一体化，横向是指收编和自己类似其他的产业或产品，纵向是指把与自己相关的原材料、再加工这些产业链上下游收编进来。当然，如果企业不差钱，还可以完全不讲逻辑，东一榔头西一棒锤地搞投资。</p><p>React 从 0.14 版一直到最新的 18 版，扩张是相当克制的。横向来看，在类组件体系基础上加入了函数组件 +Hooks；纵向来看，收编了 Redux 的部分功能（useReducer）。其他就算加进来也无可厚非的功能，比如前端路由、表单验证、服务器通信，React 框架一概不碰，完全交给 React 生态圈来补足。</p><p>React 后面的版本会发生什么？你如果感兴趣可以多关注它的官方博客。我个人也比较好奇，它会不会继续克制，或者在一定程度上转换关注点。</p><p>React 之外的前端技术也在蓬勃发展。就像之前提到的，历史的车轮会一直向前，但技术的轮子会时不时往回滚。比如当网络延迟和服务器算力不再成为系统设计的瓶颈时，把重心放到服务器端的前端技术又卷土重来了（参考最近出圈的htmx技术）。</p><h2 id="写在最后" tabindex="-1">写在最后 <a class="header-anchor" href="#写在最后" aria-label="Permalink to &quot;写在最后&quot;">​</a></h2><p>给你分享两件我做专栏记忆最深刻的事。</p><ol><li><p>对我来说，做专栏最难的部分，竟然是录音。我也说了几十年的话了，日常生活、工作中说话没有任何障碍，但朗读专栏的音频稿，就是会一而再再而三地出错。别的老师录一节课用40 分钟，我却需要 2 个小时以上，录音笔的录音文件序号已近 1800 了。我建议你平时也可以试试录音这件事，还是挺锻炼人的。在这里，要感谢我夫人、老板和同事们的鼓励和支持。</p></li><li><p>我家养了两只猫，姐姐会坐在我键盘旁边看我打字，看我卡文时还会帮我敲几行进去（你看到的文稿中至少有 100 字是她敲的）；弟弟则会半夜踱步到书房门口，陪我熬夜写稿，但每次陪不到两分钟他自己就睡着了。</p></li></ol><p>当然，最想感谢的还是陪我到结束语的你。你的学习、认真留言是我写作的最大动力。希望这个专栏能够助力你的 React Web 开发独当一面，帮助你在未来的工作中，把握住前端技术的变与不变，以成长，应万变。</p><p>我知道很多同学都喜欢“潜水”，但是在专栏的最后，我希望你能分享一下你的学习方法。此外，我给你准备了一份毕业调查问卷，题目不多，希望你花两分钟填写一下，我会认真倾听你对这个专栏的意见或建议，期待你的反馈。</p><p>最后，再次感谢！不说再见，我们留言区见。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%8E%B0%E4%BB%A3ReactWeb%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%8E%B0%E4%BB%A3ReactWeb%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/1.png" alt=""></a></p>',34)])])}const b=a(i,[["render",l]]);export{h as __pageData,b as default};
